<template><dialog ref="dialog" class="community-dialog" aria-labelledby="community-confirm-title" @close="closed" @cancel="cancel"><form @submit.prevent="emit('confirm')"><h2 id="community-confirm-title">{{ title }}</h2><p>{{ description }}</p><slot/><p v-if="error" role="alert">{{ error }}</p><div class="community-actions"><button type="button" class="button button-outline" :disabled="busy" autofocus @click="dialog.close()">Giữ lại</button><button class="button button-primary" :disabled="busy">{{ busy?'Đang xử lý…':confirmLabel }}</button></div></form></dialog></template>
<script setup>
import {ref} from 'vue';const props=defineProps({title:String,description:String,busy:Boolean,error:String,confirmLabel:{type:String,default:'Xác nhận'}}),emit=defineEmits(['confirm','close']);const dialog=ref(null);let trigger;function open(){trigger=document.activeElement;dialog.value.showModal();}function close(){dialog.value.close();}function closed(){trigger?.focus();emit('close');}function cancel(event){if(props.busy)event.preventDefault();}defineExpose({open,close});
</script>
